head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods10025";
scwin.fail = undefined;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — regSuc, mailSuc

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods10025.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txt_p19", attr: "__html", fn: function () { return ([String(String((dma_pageContext.get("corpUsrNm") ?? ""))), String(String((dma_pageContext.get("usrId") ?? ""))), String(String((dma_pageContext.get("corpNm") ?? ""))), String(String((dma_pageContext.get("isurCd") ?? "")))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("<span>" + String(String((dma_pageContext.get("corpUsrNm") ?? ""))) + "(" + String(String((dma_pageContext.get("usrId") ?? ""))) + ")</span>님의 " + String(String((dma_pageContext.get("corpNm") ?? ""))) + "[" + String(String((dma_pageContext.get("isurCd") ?? ""))) + "] 현업담당자 가입신청이 완료되었습니다.") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"fail":"fail"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_2", fn: function(){ return ((dma_pageContext.get("regSuc") ?? "") === 1 && (dma_pageContext.get("mailSuc") ?? "")===1); } }, { id: "c_when_4", fn: function(){ return ((dma_pageContext.get("regSuc") ?? "") === 1 && (dma_pageContext.get("mailSuc") ?? "")===0); } }, { id: "c_when_6", fn: function(){ return ((dma_pageContext.get("regSuc") ?? "") === 1 && (dma_pageContext.get("mailSuc") ?? "")=== -1); } }, { id: "c_otherwise_8", fn: function(){ return (!(((dma_pageContext.get("regSuc") ?? "") === 1 && (dma_pageContext.get("mailSuc") ?? "")===1) || ((dma_pageContext.get("regSuc") ?? "") === 1 && (dma_pageContext.get("mailSuc") ?? "")===0) || ((dma_pageContext.get("regSuc") ?? "") === 1 && (dma_pageContext.get("mailSuc") ?? "")=== -1))); } }, { id: "txt_p19", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.fail !== "undefined" && scwin.fail !== null ? scwin.fail : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "fail" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("fail")) !== 'fail'); } }, { id: "txt_p20", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.fail !== "undefined" && scwin.fail !== null ? scwin.fail : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "fail" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("fail")) !== 'fail'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — jldods10025: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
